use genewars_assets::{ConqMissionSource,TextStringTable};
use genewars_runtime::{actor_world::ActorWorld,actor_pool::ActorHandleBindings,actor_activation::TrigTables,actor_resources::{ActorAnimationDatabase,actor_resource_spec},blueprint::{BlueprintRng,BlueprintNames},player_state::{PlayerState,ActorOriginSample},physics_tables::PhysicsTables,landing_effect_lifecycle::RetirementUiState};
use std::{fs,path::Path};fn word(b:&[u8],p:usize)->i16{i16::from_le_bytes(b[p..p+2].try_into().unwrap())}
fn main(){let seed=std::env::args().nth(2).unwrap().parse::<u16>().unwrap();let base=std::env::args().nth(1).unwrap();let base=Path::new(&base);let runtime=base.join("private/integration/game-runtime");let bytes=fs::read(runtime.join("terrain/CONQ001.DAT")).unwrap();let src=ConqMissionSource::parse(&bytes).unwrap();let physics=PhysicsTables::from_mapped_bytes(&fs::read(runtime.join("physics/angle.bin")).unwrap(),&fs::read(runtime.join("physics/bounce.bin")).unwrap()).unwrap();let trig=TrigTables::generate_pinned().unwrap();let text=fs::read(runtime.join("menu/text.dat")).unwrap();let strings=TextStringTable::parse(&text).unwrap();let names=BlueprintNames::new(&strings.strings()[..128]).unwrap();let funds=std::env::args().nth(3).unwrap().parse::<i32>().unwrap();let work_arg=std::env::args().nth(4).unwrap();let work=Path::new(&work_arg);let players=std::array::from_fn(|p|{let player=PlayerState::fresh_campaign(p as u8,[20736,13568],b"fixture\0").unwrap();let mut r=*player.bytes();if p==0{r[0x4a3..0x4a7].copy_from_slice(&funds.to_le_bytes());}PlayerState::from_record(&r).unwrap()});let mut world=ActorWorld::from_mission(&src,&[[0;200];20],[ActorHandleBindings::empty();20],players,BlueprintRng{seed,ring:0,draw_count:0}).unwrap();world.admit_creatures(&[[0;124];300]).unwrap();world.admit_effects(&[[0;81];200],[None;200]).unwrap();world.admit_plants(&fs::read(runtime.join("plant-parameters.bin")).unwrap()).unwrap();world.regenerate_player_blueprints(0,[0;36],&names,true).unwrap();let origin=ActorOriginSample{position:[0,0],height:genewars_core::cd_candidate::interpolate_height(world.map(),0,0).unwrap(),shade:genewars_core::cd_candidate::interpolate_entity_shade(world.map(),0,0).unwrap()};world.prepare_fresh_player(0,5,origin,[20736,13568]).unwrap();world.create_landing_core(0,0).unwrap();world.apply_reveal_4096([20736,13568]).unwrap();let context=world.mission_loading_physics();let ui=RetirementUiState::native_empty();for _ in 1..=189{world.step_landing_effect_callbacks(context,&physics,&trig,&ui).unwrap();}
println!("landingseed={} draws={}",world.rng().seed,world.rng().draw_count);
let resources=(0..2).map(|id|{let a=world.actors().record(id).unwrap();let key=world.actors().bindings(id).unwrap().animation_database.unwrap();let spec=actor_resource_spec(key).unwrap();println!("id={id} key={key:?} pos={:?} pending={:?}",[word(a,7),word(a,9)],[word(a,92),word(a,94)]);ActorAnimationDatabase::load(key,fs::read(base.join(format!("private/integration/sprites/{}.anb",spec.decoded_sha256))).unwrap()).unwrap()}).collect::<Vec<_>>();
for frame in 190..=450 {
if frame==190 {let before=world.clone();assert!(world.step_actor_callbacks_in_player_order(4,frame,context,&physics,&trig,&resources[..1],0,0).is_err());assert_eq!(world,before);println!("late resource failure rollback passed");}
if frame==310 {println!("reorder={:?}",world.apply_bounded_move_order_owned(0,0,[20736,13568]).unwrap());}
let callbacks=world.step_actor_callbacks_in_player_order(4,frame,context,&physics,&trig,&resources,0,0).unwrap();
for r in callbacks {let id=r.actor_id;let a=world.actors().record(id as usize).unwrap();let _=(id,a,r);}
world.step_landing_effect_callbacks(context,&physics,&trig,&ui).unwrap();}
let site=[19839,12927];println!("siteorder={:?}",world.apply_bounded_move_order_owned(0,0,site).unwrap());
let mut next=451;
for frame in 451..=2500{world.step_actor_callbacks_in_player_order(4,frame,context,&physics,&trig,&resources,0,0).unwrap();world.step_landing_effect_callbacks(context,&physics,&trig,&ui).unwrap();let a=world.actors().record(0).unwrap();if a[0x55]==1&&[word(a,7),word(a,9)]==site{println!("sitearrival={frame}");next=frame+1;break;}if frame==2500{panic!("site not reached");}}
world.assign_architect_construction(0,0,0x100,false,false).unwrap();world.begin_pending_architect_task(0,&fs::read(work.join("border.bin")).unwrap().try_into().unwrap()).unwrap();
let records=std::array::from_fn(|_|{let mut r=[0;176];r[12..14].copy_from_slice(&(-1i16).to_le_bytes());r});let mut jobs=genewars_runtime::terrain_job_pool::TerrainJobPool::admit(records,0).unwrap();let border:[u8;8192]=fs::read(work.join("border.bin")).unwrap().try_into().unwrap();let env=genewars_runtime::construction_maintenance::TerrainEnvironment{climate_center:[0,0],raw_water_height:816,climate:106,light:[181,0,-181]};let key=world.actors().bindings(0).unwrap().animation_database.unwrap();let resource=resources.iter().find(|r|r.key()==key).unwrap();
let mut completed=false;
for frame in next..next+300{let r=world.step_architect_terraform_callback(0,frame,context,&physics,&trig,&mut jobs,&border,resource).unwrap();let a=world.actors().record(0).unwrap();println!("constructionframe={frame} stage={} action={} anim={} ready={:x} jobs={} draws={}",word(a,0x88),a[0x59],a[0x19],a[0x49],jobs.count(),world.rng().draw_count);if r.terraform.is_some(){fs::write(work.join("action13.bin"),a).unwrap();let handle=world.actors().bindings(0).unwrap().blueprint.unwrap();fs::write(work.join("blueprint.bin"),world.player(handle.player_id).unwrap().blueprint(handle.blueprint_index as usize).unwrap()).unwrap();println!("action13key={key:?}");}if r.terraform_completion.is_some(){completed=true;next=frame+1;break;}world.step_terrain_jobs_without_height_changes(&mut jobs,env,&border).unwrap();}
assert!(completed,"terraform did not finish");
for frame in next..next+300{
 let receipt=world.step_architect_construction_callback(0,frame,context,&physics,&trig,&mut jobs,&border,resource,false,false).unwrap();
 if let Some(payment)=receipt.payment{println!("paymentframe={frame}");println!("paymentcost={} fundsafter={}",payment.cost,i32::from_le_bytes(world.player(0).unwrap().bytes()[0x4a3..0x4a7].try_into().unwrap()));assert!(funds>=688);let a=world.actors().record(0).unwrap();assert_eq!(a[0x59],14);assert_eq!(a[0x19],14);fs::write(work.join("action14-after-tail.bin"),a).unwrap();println!("action14key={key:?} frame={}",a[0x1b]);break;}
 if let Some(cancellation)=receipt.cancellation{println!("paymentframe={frame}");assert_eq!(funds,0);println!("paymentrefused=InsufficientCancellationRequired");println!("cancelled task={} state={} mode={} funds=0",cancellation.after[0x82],cancellation.after[0x55],cancellation.after[0x7e]);break;}
}

}
